patterns.recipe:
-- CALL 1 (cascaded/inherited children, one call):
SELECT c.oid::regclass::text AS child, query_to_xml('SELECT * FROM ONLY ' || c.oid::regclass::text, true, false, '') AS data FROM pg_inherits i JOIN pg_class c ON c.oid=i.inhrelid WHERE i.inhparent='<SCHEMA>.<TABLE>'::regclass;
-- CALL 2 (rows matching the DELETE's own WHERE)
INSERT INTO <TABLE> (<COL1>, <COL2>, ...) VALUES (<CAPTURED_VAL1>, ...);
-- and one INSERT per child, from CALL 1
